import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`literature-review`,heroTitle:`Build your literature review in minutes`,heroSubtitle:`Perplexity Computer searches key journals, summarizes top papers, and maps debates and open questions — automatically.`,inputUrlCta:`Review my topic`,inputUrlPlaceholder:`e.g. CRISPR gene therapy`,inputUrlPrefill:`Take the following research topic or question: {url}. 1) Search across key academic journals and databases to identify the 10–20 most-cited and most-recent influential papers in this area. 2) For each paper, write a plain-English summary covering core findings, methodology used, and key limitations. 3) Map the main debates, theoretical tensions, and open questions across the literature — identifying where researchers agree, disagree, and where gaps remain. 4) Produce a prioritized reading list organized by importance, with a note on what each paper changed or contributed to the field. 5) Include a synthesis section that shows how the papers connect to each other and to the original research question. Format everything in a clean, structured document I can use as a foundation for my own literature review.`,heroOverlaySteps:[`Searching academic databases for the most influential papers on your topic`,`Summarizing core findings, methodology, and limitations for each paper`,`Mapping key debates, agreements, and open questions across the literature`,`Prioritized reading list with contribution notes — ready to review`],generatingSteps:[`Analyzing {url} to identify the research scope, keywords, and related subfields`,`Designing an agent to search top journals and rank papers by citation impact and recency`,`Configuring plain-English summarization for findings, methods, and limitations`,`Setting up debate mapping and prioritized reading list generation`],featureSectionTitle:`From research question to structured review`,featureCardTitles:[`Connects to your research stack`,`Outputs you can cite`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Drive, Notion, Google Sheets, Airtable — Computer delivers your literature review and reading list straight into the tools you already use.`,`Plain-English paper summaries. Methodology and limitation breakdowns. Debate and gap maps. A prioritized reading list with contribution notes for every paper.`],capabilitySectionTitle:`Your research assistant, on autopilot`,capabilitySectionSubtitle:`Enter your topic, step away, come back to a complete literature review.`,capabilityCards:[{title:`Paper Discovery`,description:`Computer can search key journals and databases to find the 10–20 most-cited and most-recent influential papers on your research topic.`},{title:`Paper Summaries`,description:`Computer can write plain-English summaries of each paper — covering core findings, methodology, and key limitations in a consistent format.`},{title:`Debate Mapping`,description:`Computer can identify the main theoretical tensions, points of consensus, and open questions across the literature — so you see the field, not just individual papers.`},{title:`Connect Your Tools`,description:`Computer can export to Google Docs, Notion, Google Sheets, and Google Drive — build workflows across your entire research and writing stack.`},{title:`Remember & Refine`,description:`Computer can remember your research topics, past reviews, and preferred sources across sessions — so each new search builds on what you've already explored.`},{title:`Monitor & Alert`,description:`Computer can re-scan your topic weekly and flag newly published papers, emerging debates, or citation shifts that affect your review.`}]});export{t as default};
